CREATE TABLE IF NOT EXISTS rsvps (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, attendance TEXT NOT NULL, guests INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS guestbook (id TEXT PRIMARY KEY, name TEXT NOT NULL, relation TEXT NOT NULL DEFAULT '', message TEXT NOT NULL, date TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (ip_hash TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
